/* @lc app=leetcode id=3911 lang=kotlin */ class Solution { fun ub(a: IntArray, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= v) m + 1 to hi else lo to m } }.last().first fun kthRemainingInteger(nums: IntArray, queries: Array<IntArray>): IntArray = nums.runningFold(0) { a, x -> a + (if (x % 2 == 0) 1 else 0) }.let { E -> queries.map { (l, r, k) -> generateSequence(1L to k.toLong() + nums.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { h -> (maxOf(l, minOf(r + 1, ub(nums, 2 * h)))).let { t -> if (h - (E[t] - E[l]) >= k) lo to h else h + 1 to hi } } }.last().first.let { (2 * it).toInt() } }.toIntArray() } }